/** Shared job types, validation, and serialization used by the server and the worker. */

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** A row of the `jobs` table, as stored. Internal columns are never exposed directly. */
export interface JobRow {
  seq: number;
  id: string;
  input: string;
  steps: number;
  fail_attempts: number;
  status: JobStatus;
  attempts: number;
  completed: number;
  output: string | null;
  error: string | null;
  idempotency_key: string | null;
  payload: string;
  created_at: string;
  updated_at: string;
  eligible_at: number;
}

/** The public job representation returned by every endpoint that returns a job. */
export interface PublicJob {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

export function serializeJob(row: JobRow): PublicJob {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.completed, total: row.steps },
    result: row.status === 'completed' ? { output: row.output ?? '' } : null,
    error: row.status === 'failed' ? (row.error ?? '') : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

export interface FieldError {
  field: string;
  message: string;
}

export interface Submission {
  input: string;
  steps: number;
  failAttempts: number;
}

export type ParsedSubmission =
  | { ok: true; submission: Submission; key: string | null; payload: string }
  | { ok: false; errors: FieldError[] };

const KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;
const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const MAX_INPUT_LENGTH = 1000;

const hasOwn = (obj: Record<string, unknown>, key: string): boolean => Object.prototype.hasOwnProperty.call(obj, key);

function isIntegerIn(v: unknown, min: number, max: number): v is number {
  return typeof v === 'number' && Number.isInteger(v) && v >= min && v <= max;
}

/**
 * Validates a submission and collects every independently detectable error. On success, returns
 * the submission with defaults applied and a normalized payload string used for idempotency
 * comparison.
 */
export function parseSubmission(
  contentType: string | undefined,
  bodyText: string,
  idempotencyKey: string | undefined,
): ParsedSubmission {
  const errors: FieldError[] = [];

  const mediaType = (contentType ?? '').split(';')[0]!.trim().toLowerCase();
  if (mediaType !== 'application/json') {
    errors.push({ field: 'body', message: 'Content-Type must be application/json.' });
  }

  let key: string | null = null;
  if (idempotencyKey !== undefined) {
    if (KEY_PATTERN.test(idempotencyKey)) key = idempotencyKey;
