import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, immediate } from './db.ts';
import { HEARTBEAT_FRESH_MS, parseSubmission, serializeJob, type FieldError, type JobRow } from './jobs.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const MAX_BODY_BYTES = 16 * 1024;

const selectAll = db.prepare('SELECT * FROM jobs ORDER BY seq DESC');
const selectById = db.prepare('SELECT * FROM jobs WHERE id = ?');
const selectByKey = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?');
const insertJob = db.prepare(
  `INSERT INTO jobs (id, input, steps, fail_attempts, status, attempts, completed, output, error,
                     idempotency_key, payload, created_at, updated_at, eligible_at)
   VALUES (?, ?, ?, ?, 'queued', 0, 0, NULL, NULL, ?, ?, ?, ?, ?)`,
);
const selectHeartbeat = db.prepare('SELECT ts FROM heartbeat WHERE id = 1');

function sendJson(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields) error.fields = fields;
  sendJson(res, status, { error });
}

/** Reads the request body as text. Oversized bodies are drained and reported as `null`. */
function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? null : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

function workerIsUp(): boolean {
  const row = selectHeartbeat.get() as { ts: number } | undefined;
  return row !== undefined && Date.now() - Number(row.ts) <= HEARTBEAT_FRESH_MS;
}

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const text = await readBody(req);
  const header = req.headers['idempotency-key'];
  const idempotencyKey = typeof header === 'string' ? header : undefined;
  const contentType = req.headers['content-type'];
  const parsed = parseSubmission(contentType, text ?? '', idempotencyKey);
  if (!parsed.ok) {
    const errors = text === null ? [{ field: 'body', message: 'Body is too large.' }, ...parsed.errors] : parsed.errors;
    sendError(res, 400, 'invalid_request', 'The request is invalid.', errors);
    return;
  }
  if (text === null) {
    sendError(res, 400, 'invalid_request', 'The request is invalid.', [{ field: 'body', message: 'Body is too large.' }]);
    return;
  }

  const { submission, key, payload } = parsed;
  const outcome = immediate(db, () => {
    if (key !== null) {
      const existing = selectByKey.get(key) as JobRow | undefined;
      if (existing) {
        if (existing.payload === payload) return { status: 200, job: serializeJob(existing) };
        return { status: 409, conflict: true as const };
      }
    }
    const id = randomUUID();
    const now = new Date();
    const iso = now.toISOString();
    insertJob.run(id, submission.input, submission.steps, submission.failAttempts, key, payload, iso, iso, now.getTime());
    const row = selectById.get(id) as JobRow;
    return { status: 201, job: serializeJob(row) };
  });

  if ('conflict' in outcome) {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
    return;
  }
  sendJson(res, outcome.status, outcome.job);
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const url = new URL(req.url ?? '/', 'http://localhost');
  const path = url.pathname;
  const method = req.method ?? 'GET';

  const methodNotAllowed = () => sendError(res, 405, 'method_not_allowed', `Method ${method} is not allowed here.`);

  if (path === '/') {
    if (method !== 'GET') return methodNotAllowed();
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }

  if (path === '/health') {
    if (method !== 'GET') return methodNotAllowed();
    sendJson(res, 200, { status: 'ok', worker: workerIsUp() ? 'up' : 'down' });
    return;
  }

  if (path === '/api/jobs') {
    if (method === 'GET') {
      const rows = selectAll.all() as unknown as JobRow[];
      sendJson(res, 200, { jobs: rows.map(serializeJob) });
      return;
    }
    if (method === 'POST') return createJob(req, res);
    return methodNotAllowed();
  }

  const match = /^\/api\/jobs\/([^/]+)$/.exec(path);
  if (match) {
    if (method !== 'GET') return methodNotAllowed();
    const row = selectById.get(match[1]!) as JobRow | undefined;
    if (!row) {
      sendError(res, 404, 'not_found', 'No job with that id.');
      return;
    }
    sendJson(res, 200, serializeJob(row));
    return;
  }

  sendError(res, 404, 'not_found', 'Not found.');
}

const server = createServer((req, res) => {
  handle(req, res).catch((err: unknown) => {
    console.error('request failed:', err);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));

let closing = false;
function shutdown(): void {
  if (closing) return;
  closing = true;
  // Stop accepting connections, let in-flight requests settle, and bound the wait.
  server.close(() => {
    try {
      db.close();
    } catch {
      // already closed
    }
    process.exit(0);
  });
  server.closeIdleConnections();
  setTimeout(() => server.closeAllConnections(), 2000).unref();
  setTimeout(() => process.exit(0), 5000).unref();
}

process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

