import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, immediate } from './db.ts';
import type { JobRow } from './jobs.ts';

const STEP_MS = 100;
const POLL_MS = 100;
const HEARTBEAT_MS = 500;
const RETRY_DELAY_MS = 500;
const MAX_ATTEMPTS = 3;

const db = openDatabase();
let stopping = false;

const selectRunning = db.prepare("SELECT * FROM jobs WHERE status = 'running' ORDER BY seq LIMIT 1");
const selectNextQueued = db.prepare("SELECT * FROM jobs WHERE status = 'queued' AND eligible_at <= ? ORDER BY seq LIMIT 1");
const claimJob = db.prepare(
  "UPDATE jobs SET status = 'running', attempts = attempts + 1, completed = 0, output = NULL, error = NULL, updated_at = ? WHERE seq = ?",
);
const selectBySeq = db.prepare('SELECT * FROM jobs WHERE seq = ?');
const setProgress = db.prepare('UPDATE jobs SET completed = ?, updated_at = ? WHERE seq = ?');
const resetProgress = db.prepare('UPDATE jobs SET completed = 0, updated_at = ? WHERE seq = ?');
const scheduleRetry = db.prepare(
  "UPDATE jobs SET status = 'queued', completed = 0, output = NULL, error = NULL, eligible_at = ?, updated_at = ? WHERE seq = ?",
);
const failJob = db.prepare(
  "UPDATE jobs SET status = 'failed', completed = 0, output = NULL, error = 'transient failure', updated_at = ? WHERE seq = ?",
);
const completeJob = db.prepare(
  "UPDATE jobs SET status = 'completed', completed = steps, output = ?, error = NULL, updated_at = ? WHERE seq = ?",
);
const upsertHeartbeat = db.prepare(
  'INSERT INTO heartbeat (id, ts) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET ts = excluded.ts',
);
const clearHeartbeat = db.prepare('DELETE FROM heartbeat');

function beat(): void {
  try {
    upsertHeartbeat.run(Date.now());
  } catch (err) {
    console.error('heartbeat failed:', err);
  }
}

/**
 * Claims the oldest queued job whose retry delay has passed. The claim is a short transaction:
 * no processing happens while the write lock is held.
 */
function claimNext(): JobRow | undefined {
  return immediate(db, () => {
    const next = selectNextQueued.get(Date.now()) as JobRow | undefined;
    if (!next) return undefined;
    claimJob.run(new Date().toISOString(), next.seq);
    return selectBySeq.get(next.seq) as JobRow;
  });
}

/**
 * Runs one attempt of a job. `attempt` is the attempt number the job is on. A recovered running
 * job replays its persisted attempt, so the attempt number is not incremented again.
 */
async function runAttempt(job: JobRow): Promise<void> {
  const attempt = job.attempts;

  if (attempt <= job.fail_attempts) {
    // Simulated transient failure at the first step, before any progress is recorded.
    await sleep(STEP_MS);
    if (stopping) return;
    immediate(db, () => {
      const now = new Date().toISOString();
      if (attempt >= MAX_ATTEMPTS) failJob.run(now, job.seq);
      else scheduleRetry.run(Date.now() + RETRY_DELAY_MS, now, job.seq);
    });
    return;
  }

  // Replaying a recovered attempt starts progress from zero again.
  immediate(db, () => resetProgress.run(new Date().toISOString(), job.seq));

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return; // stop at a step boundary; the job stays running and is recovered later
    immediate(db, () => setProgress.run(step, new Date().toISOString(), job.seq));
  }

  // Use JavaScript's toUpperCase, not SQLite's upper(), as the contract requires.
  const output = job.input.toUpperCase();
  immediate(db, () => completeJob.run(output, new Date().toISOString(), job.seq));
}

async function main(): Promise<void> {
  beat();
  const heartbeat = setInterval(beat, HEARTBEAT_MS);

  try {
    while (!stopping) {
      try {
        // Recovery first: a running job can only be left over from an earlier worker process.
        const running = selectRunning.get() as JobRow | undefined;
        if (running) {
          await runAttempt(running);
          continue;
        }
        const next = claimNext();
        if (next) {
          await runAttempt(next);
          continue;
        }
      } catch (err) {
        console.error('worker iteration failed:', err);
        await sleep(POLL_MS * 5);
        continue;
      }
      await sleep(POLL_MS);
    }
  } finally {
    clearInterval(heartbeat);
    try {
      clearHeartbeat.run();
    } catch {
      // the heartbeat expires on its own
    }
    db.close();
  }
}

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

console.log('worker started');
main()
  .then(() => {
    console.log('worker stopped');
    process.exit(0);
  })
  .catch((err: unknown) => {
    console.error('worker failed:', err);
    process.exit(1);
  });

